<?php

namespace App\Evaluation;

use App\Query\ObjectDescription;
use Symfony\AI\Platform\Message\Content\Image;

/**
 * The query photo's description, generated once and kept.
 *
 * A text reranker cannot see a photograph, so it is handed a description
 * instead. That description is generated by a model and is therefore not
 * reproducible for free: calling it twice can give two different sentences.
 * Caching it is what makes "same text, different reranker" a fair comparison
 * rather than a measurement of gpt-4o-mini's mood.
 */
final class CaptionCache
{
    /** @var array<string, array<string, string>> model => key => caption */
    private array $captions;

    public function __construct(
        private readonly ObjectDescription $description,
        private readonly string $directory,
    ) {
        $this->captions = [];
    }

    /**
     * The caption for a photo under a given model and prompt. Each combination
     * keeps its own file, so two captioners — or one captioner asked two
     * different questions — can be compared without one overwriting the other.
     */
    public function of(Image $image, string $key, string $model, string $prompt = 'appearance'): string
    {
        $variant = $model . '--' . $prompt;
        $this->load($variant);

        if (isset($this->captions[$variant][$key])) {
            return $this->captions[$variant][$key];
        }

        // Written back onto the property, not a copy: a local array would be
        // discarded and the next call would reload a stale file, so only the
        // last caption would ever survive on disk.
        $this->captions[$variant][$key] = $this->description->of($image, $model, $prompt);
        $this->save($variant);

        return $this->captions[$variant][$key];
    }

    /**
     * @return array<string, string>
     */
    private function load(string $variant): array
    {
        if (isset($this->captions[$variant])) {
            return $this->captions[$variant];
        }

        $path = $this->pathFor($variant);
        $this->captions[$variant] = is_file($path)
            ? (array) json_decode((string) file_get_contents($path), true)
            : [];

        return $this->captions[$variant];
    }

    private function save(string $variant): void
    {
        if (!is_dir($this->directory)) {
            mkdir($this->directory, 0o777, true);
        }

        file_put_contents(
            $this->pathFor($variant),
            json_encode($this->captions[$variant], \JSON_PRETTY_PRINT),
        );
    }

    private function pathFor(string $variant): string
    {
        return $this->directory . '/' . preg_replace('/[^a-z0-9.-]/i', '-', $variant) . '.json';
    }
}
